1	package pipedrive
2	
3	import (
4		"context"
5		"errors"
6		"io"
7		"math"
8		rand "math/rand/v2"
9		"net/http"
10		"time"
11	)
12	
13	type RetryPolicy struct {
14		MaxAttempts int
15		BaseDelay   time.Duration
16		MaxDelay    time.Duration
17	
18		// MaxRetryAfter caps how long a server-provided Retry-After header may
19		// delay a retry, so a misbehaving server cannot pin the client
20		// indefinitely. Zero uses the 1 minute default; negative disables the
21		// cap.
22		MaxRetryAfter time.Duration
23	
24		Jitter func(time.Duration) time.Duration
25	
26		RetryAllMethods bool
27	}
28	
29	const defaultMaxRetryAfter = time.Minute
30	
31	func DefaultRetryPolicy() RetryPolicy {
32		return RetryPolicy{
33			MaxAttempts:     4,
34			BaseDelay:       200 * time.Millisecond,
35			MaxDelay:        5 * time.Second,
36			MaxRetryAfter:   defaultMaxRetryAfter,
37			Jitter:          fullJitter,
38			RetryAllMethods: false,
39		}
40	}
41	
42	type retryTransport struct {
43		next   http.RoundTripper
44		policy RetryPolicy
45		opts   retryTransportOptions
46	}
47	
48	type retryTransportOptions struct {
49		sleep func(context.Context, time.Duration) error
50		now   func() time.Time
51	}
52	
53	func newRetryTransport(next http.RoundTripper, policy RetryPolicy, opts retryTransportOptions) http.RoundTripper {
54		if next == nil {
55			next = http.DefaultTransport
56		}
57		policy = sanitizeRetryPolicy(policy)
58		if opts.sleep == nil {
59			opts.sleep = sleepWithContext
60		}
61		if opts.now == nil {
62			opts.now = time.Now
63		}
64		return &retryTransport{
65			next:   next,
66			policy: policy,
67			opts:   opts,
68		}
69	}
70	
71	func (t *retryTransport) RoundTrip(req *http.Request) (*http.Response, error) {
72		if req == nil {
73			return nil, errors.New("pipedrive: nil request")
74		}
75	
76		policy := t.policy
77		if override, ok := retryPolicyFromContext(req.Context()); ok {
78			policy = sanitizeRetryPolicy(override)
79		}
80	
81		if isNoRetry(req.Context()) || policy.MaxAttempts <= 1 {
82			return t.next.RoundTrip(req)
83		}
84	
85		origGetBody := req.GetBody
86		canReplayBody := req.Body == nil || req.Body == http.NoBody || origGetBody != nil
87	
88		for attempt := 1; ; attempt++ {
89			attemptReq := req
90			if attempt > 1 {
91				attemptReq = req.Clone(req.Context())
92				if origGetBody != nil {
93					body, err := origGetBody()
94					if err != nil {
95						return nil, err
96					}
97					attemptReq.Body = body
98				}
99			}
100	
101			resp, err := t.next.RoundTrip(attemptReq)
102			if !t.shouldRetry(attempt, attemptReq, canReplayBody, resp, err, policy) {
103				return resp, err
104			}
105	
106			delay := t.nextDelay(attempt, resp, policy)
107			if resp != nil && resp.Body != nil {
108				_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<20))
109				_ = resp.Body.Close()
110			}
111	
112			if delay > 0 {
113				if err := t.opts.sleep(req.Context(), delay); err != nil {
114					return nil, err
115				}
116			}
117		}
118	}
119	
120	func (t *retryTransport) shouldRetry(attempt int, req *http.Request, canReplayBody bool, resp *http.Response, err error, policy RetryPolicy) bool {
121		if err != nil || resp == nil {
122			return false
123		}
124		if attempt >= policy.MaxAttempts {
125			return false
126		}
127	
128		switch resp.StatusCode {
129		case 429:
130			return canReplayBody
131		case 502, 503, 504:
132			if !canReplayBody {
133				return false
134			}
135			return policy.RetryAllMethods || isIdempotentMethod(req.Method)
136		default:
137			return false
138		}
139	}
140	
141	func (t *retryTransport) nextDelay(attempt int, resp *http.Response, policy RetryPolicy) time.Duration {
142		if resp != nil && resp.StatusCode == 429 {
143			if ra := parseRetryAfter(resp.Header.Get("Retry-After"), t.opts.now()); ra > 0 {
144				if policy.MaxRetryAfter > 0 && ra > policy.MaxRetryAfter {
145					ra = policy.MaxRetryAfter
146				}
147				return ra
148			}
149		}
150	
151		if policy.BaseDelay <= 0 {
152			return 0
153		}
154	
155		exp := float64(policy.BaseDelay) * math.Pow(2, float64(attempt-1))
156		delay := time.Duration(exp)
157		if delay > policy.MaxDelay {
158			delay = policy.MaxDelay
159		}
160		return policy.Jitter(delay)
161	}
162	
163	func isIdempotentMethod(method string) bool {
164		switch method {
165		case http.MethodGet, http.MethodHead, http.MethodPut, http.MethodDelete, http.MethodOptions, http.MethodTrace:
166			return true
167		default:
168			return false
169		}
170	}
171	
172	func fullJitter(d time.Duration) time.Duration {
173		if d <= 0 {
174			return 0
175		}
176		// #nosec G404 -- Retry jitter only needs inexpensive non-cryptographic randomness.
177		return time.Duration(rand.Int64N(int64(d)))
178	}
179	
180	func sleepWithContext(ctx context.Context, d time.Duration) error {
181		if d <= 0 {
182			return nil
183		}
184		timer := time.NewTimer(d)
185		defer timer.Stop()
186		select {
187		case <-timer.C:
188			return nil
189		case <-ctx.Done():
190			return ctx.Err()
191		}
192	}
193	
194	type noRetryKey struct{}
195	
196	func withNoRetry(ctx context.Context) context.Context {
197		return context.WithValue(ctx, noRetryKey{}, true)
198	}
199	
200	func isNoRetry(ctx context.Context) bool {
201		disabled, _ := ctx.Value(noRetryKey{}).(bool)
202		return disabled
203	}
204	
205	type retryPolicyKey struct{}
206	
207	func withRetryPolicy(ctx context.Context, policy RetryPolicy) context.Context {
208		return context.WithValue(ctx, retryPolicyKey{}, policy)
209	}
210	
211	func retryPolicyFromContext(ctx context.Context) (RetryPolicy, bool) {
212		policy, ok := ctx.Value(retryPolicyKey{}).(RetryPolicy)
213		return policy, ok
214	}
215	
216	func sanitizeRetryPolicy(policy RetryPolicy) RetryPolicy {
217		if policy.MaxAttempts <= 0 {
218			policy.MaxAttempts = 1
219		}
220		if policy.BaseDelay < 0 {
221			policy.BaseDelay = 0
222		}
223		if policy.MaxDelay <= 0 {
224			policy.MaxDelay = policy.BaseDelay
225		}
226		if policy.MaxRetryAfter == 0 {
227			policy.MaxRetryAfter = defaultMaxRetryAfter
228		}
229		if policy.Jitter == nil {
230			policy.Jitter = func(d time.Duration) time.Duration { return d }
231		}
232		return policy
233	}
