func TestRetryTransport_NilRequestReturnsError(t *testing.T) {
	t.Parallel()

	rt := newRetryTransport(roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		t.Fatalf("unexpected call to next transport")
		return nil, nil
	}), DefaultRetryPolicy(), retryTransportOptions{})

	_, err := rt.RoundTrip(nil)
	if err == nil {
		t.Fatalf("expected error")
	}
	if err.Error() != "pipedrive: nil request" {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestRetryHelpers(t *testing.T) {
	t.Parallel()

	for _, method := range []string{
		http.MethodGet,
		http.MethodHead,
		http.MethodPut,
		http.MethodDelete,
		http.MethodOptions,
		http.MethodTrace,
	} {
		if !isIdempotentMethod(method) {
			t.Fatalf("expected %s to be idempotent", method)
		}
	}
	for _, method := range []string{http.MethodPost, http.MethodPatch, "CUSTOM"} {
		if isIdempotentMethod(method) {
			t.Fatalf("expected %s to be non-idempotent", method)
		}
	}

	if got := fullJitter(0); got != 0 {
		t.Fatalf("fullJitter(0) = %s, want 0", got)
	}
	if got := fullJitter(-time.Second); got != 0 {
		t.Fatalf("fullJitter(-1s) = %s, want 0", got)
	}
	for i := 0; i < 20; i++ {
		if got := fullJitter(10 * time.Millisecond); got < 0 || got >= 10*time.Millisecond {
			t.Fatalf("fullJitter out of range: %s", got)
		}
	}
}

func TestSleepWithContext_ReturnsOnCancel(t *testing.T) {
	t.Parallel()

	if err := sleepWithContext(context.Background(), 0); err != nil {
		t.Fatalf("zero sleep error: %v", err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	err := sleepWithContext(ctx, time.Hour)
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("expected context canceled, got %v", err)
	}
}

func TestSanitizeRetryPolicy_ClampsInvalidValues(t *testing.T) {
	t.Parallel()

	policy := sanitizeRetryPolicy(RetryPolicy{
		MaxAttempts: -3,
		BaseDelay:   -time.Second,
		MaxDelay:    0,
		Jitter:      nil,
	})

	if policy.MaxAttempts != 1 {
		t.Fatalf("expected max attempts 1, got %d", policy.MaxAttempts)
	}
	if policy.BaseDelay != 0 {
		t.Fatalf("expected base delay 0, got %s", policy.BaseDelay)
	}
	if policy.MaxDelay != 0 {
		t.Fatalf("expected max delay 0, got %s", policy.MaxDelay)
	}
	if policy.Jitter == nil {
		t.Fatalf("expected default jitter")
	}
	if got := policy.Jitter(3 * time.Second); got != 3*time.Second {
		t.Fatalf("unexpected default jitter result: %s", got)
	}

	policy = sanitizeRetryPolicy(RetryPolicy{
		MaxAttempts: 2,
		BaseDelay:   time.Second,
		MaxDelay:    -time.Second,
		Jitter:      func(d time.Duration) time.Duration { return d / 2 },
	})
	if policy.MaxDelay != time.Second {
		t.Fatalf("expected max delay to default to base delay, got %s", policy.MaxDelay)
	}
	if got := policy.Jitter(4 * time.Second); got != 2*time.Second {
		t.Fatalf("unexpected custom jitter result: %s", got)
	}
}

package pipedrive

import "net/http"

type Middleware func(next http.RoundTripper) http.RoundTripper

func chainMiddleware(base http.RoundTripper, middleware []Middleware) http.RoundTripper {
	rt := base
	for i := len(middleware) - 1; i >= 0; i-- {
		rt = middleware[i](rt)
	}
	return rt
}

package pipedrive

import "net/http"

type Config struct {
	// BaseURL is the API origin requests are sent to. When set, credentials
	// from Auth are only attached to requests targeting this origin (scheme
	// and host), including redirect hops — a cross-origin redirect target
	// never receives them. When empty, Auth applies to every request made
	// through the client, but a redirect that leaves the initial request's
	// origin still suppresses credentials on that hop.
	//
	// The value must be an absolute URL with a scheme and host, e.g.
	// "https://api.pipedrive.com". A value that lacks either fails closed:
	// credentials are withheld from every request rather than sent
	// somewhere unintended, which surfaces as authentication errors from
	// the API. v1/v2 NewClient reject such values; NewHTTPClient cannot
	// return an error, so it withholds silently.
	BaseURL string

	// OAuthBaseURL is the origin the v1 OAuth service uses for authorize
	// URLs and token exchange/refresh. Empty uses the production default
	// (https://oauth.pipedrive.com). Requests to it authenticate with
	// explicit client credentials; Auth is never attached.
	OAuthBaseURL string

	HTTPClient *http.Client

	Middleware []Middleware

	RetryPolicy *RetryPolicy

	// MaxResponseSize caps successful response bodies in bytes.
	// Zero uses the default 64 MiB cap. Negative values disable the cap.
	MaxResponseSize int64

	UserAgent string
	Auth      AuthProvider
}

func NewHTTPClient(cfg Config) *http.Client {
	base := cfg.HTTPClient
	if base == nil {
		base = http.DefaultClient
	}

	clone := new(http.Client)
	*clone = *base

	transport := clone.Transport
	if transport == nil {
		transport = http.DefaultTransport
	}

	origin := authOriginFromBaseURL(cfg.BaseURL)

	middleware := make([]Middleware, 0, len(cfg.Middleware)+2)
	middleware = append(middleware, cfg.Middleware...)
	if cfg.UserAgent != "" {
		middleware = append(middleware, userAgentMiddleware(cfg.UserAgent))
	}
	if cfg.Auth != nil {
		middleware = append(middleware, authMiddleware(cfg.Auth, origin))
	}

	// Catches credential headers set directly on the request (for example
	// through WithHeader), which the auth middleware never sees, and marks
	// off-scope hops so the middleware does not re-attach Auth credentials.
	clone.CheckRedirect = redirectCredentialGuard(origin, base.CheckRedirect)

	transport = newResponseLimitTransport(transport, cfg.MaxResponseSize)
	transport = chainMiddleware(transport, middleware)

	policy := cfg.RetryPolicy
	if policy == nil {
		p := DefaultRetryPolicy()
		policy = &p
	}
	transport = newRetryTransport(transport, *policy, retryTransportOptions{})

	clone.Transport = transport
	return clone
}

