	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	body := seekableBody{ReadSeeker: bytes.NewReader([]byte("payload"))}
	var out struct {
		Ok bool `json:"ok"`
	}
	if err := raw.Do(context.Background(), http.MethodPost, "/upload", nil, body, &out); err != nil {
		t.Fatalf("Do error: %v", err)
