package multipartbody

import (
	"io"
	"mime"
	"mime/multipart"
	"strings"
	"testing"
)

func TestNewFile_EncodesSingleFilePart(t *testing.T) {
	t.Parallel()

	contentType, body, err := NewFile("file", "doc.txt", strings.NewReader("hello"))
	if err != nil {
		t.Fatalf("NewFile error: %v", err)
	}

	parts := readParts(t, contentType, body)
	if len(parts) != 1 {
		t.Fatalf("expected 1 part, got %d", len(parts))
	}
	if parts[0].name != "file" || parts[0].filename != "doc.txt" || parts[0].value != "hello" {
		t.Fatalf("unexpected part: %#v", parts[0])
	}
}

func TestNewFileWithFields_WritesFileAndFields(t *testing.T) {
	t.Parallel()

	fields := []Field{
		{Name: "deal_id", Value: "42"},
		{Name: "person_id", Value: "7"},
	}
	contentType, body, err := NewFileWithFields("file", "report.pdf", strings.NewReader("data"), fields)
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}

	parts := readParts(t, contentType, body)
	if len(parts) != 3 {
		t.Fatalf("expected 3 parts, got %d", len(parts))
	}
	if parts[0].filename != "report.pdf" || parts[0].value != "data" {
		t.Fatalf("unexpected file part: %#v", parts[0])
	}
	if parts[1].name != "deal_id" || parts[1].value != "42" {
		t.Fatalf("unexpected deal_id part: %#v", parts[1])
	}
	if parts[2].name != "person_id" || parts[2].value != "7" {
		t.Fatalf("unexpected person_id part: %#v", parts[2])
	}
}

func TestNewFile_Validates(t *testing.T) {
	t.Parallel()

	if _, _, err := NewFile("", "doc.txt", strings.NewReader("x")); err == nil {
		t.Fatalf("expected error for empty field name")
	}
	if _, _, err := NewFile("file", "", strings.NewReader("x")); err == nil {
		t.Fatalf("expected error for empty file name")
	}
	if _, _, err := NewFile("file", "doc.txt", nil); err == nil {
		t.Fatalf("expected error for nil content")
	}
}

type part struct {
	name     string
	filename string
	value    string
}

func readParts(t *testing.T, contentType string, body io.Reader) []part {
	t.Helper()

	_, params, err := mime.ParseMediaType(contentType)
	if err != nil {
		t.Fatalf("parse content type: %v", err)
	}
	reader := multipart.NewReader(body, params["boundary"])

	var parts []part
	for {
		p, err := reader.NextPart()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatalf("next part: %v", err)
		}
		value, err := io.ReadAll(p)
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		parts = append(parts, part{name: p.FormName(), filename: p.FileName(), value: string(value)})
	}
	return parts
}

